import numpy as np
import matplotlib.pyplot as plt

# Функция и её производная
def f(x):
    return x**4

def df(x):
    return 4*x**3

# Метод Ньютона
def newton(x0, eta=1, max_iter=10):
    x = x0
    history = [x]
    for i in range(max_iter):
        x_next = x - f(x) / df(x)
        history.append(x_next)
        if abs(x_next - x) < eta:
            break
        x = x_next
    return np.array(history)

# Градиентный спуск
def gradient_descent(x0, eta=0.1, max_iter=100):
    x = x0
    history = [x]
    for i in range(max_iter):
        x_next = x - eta * df(x)
        history.append(x_next)
        if abs(x_next - x) < eta:
            break
        x = x_next
    return np.array(history)

# Начальные условия
x0 = 2
eta = 0.01  # Шаг для градиентного спуска

# Вычисление траекторий
newton_history = newton(x0, eta=eta, max_iter=10)
gd_history = gradient_descent(x0, eta=eta, max_iter=100)

# Визуализация
plt.figure(figsize=(10, 6))
plt.plot(newton_history, marker='o', linestyle='-', label='Метод Ньютона')
plt.plot(gd_history, marker='x', linestyle='--', label='Градиентный спуск')
plt.xlabel('Итерация')
plt.ylabel('x')
plt.title('Сходимость метода Ньютона и градиентного спуска (f(x) = x⁴, x₀ = 2)')
plt.legend()
plt.grid(True)
plt.yscale('log') # логарифмический масштаб по оси y
plt.show()

print(f"Последнее значение Ньютона = {newton_history[-1]:.2f}")
print(f"Последнее значение градиентного спуска = {gd_history[-1]:.2f}")

